INSERT INTO `consumables` VALUES (1,'SealBoss FlexPUR 135 PU Injection Resin','Single-component polyurethane injection resin that reacts with water to form a flexible, closed-cell foam. Expands up to 30x its volume to seal active water leaks in concrete cracks, joints, and pipe penetrations. The go-to resin for most crack injection waterproofing jobs in Hong Kong — fast-reacting and highly effective against hydrostatic pressure.','SealBoss','FlexPUR-135','kg',380.00,'https://d2xsxph8kpxj0f.cloudfront.net/310519663429127370/EqJqhhxWWJKtKB68YEvggw/sealboss-flexpur-135_5ea3e44b.jpg','Type: Single-component PU foam | Reaction: Water-activated | Expansion: Up to 30x | Cure Time: 30-90 seconds | Viscosity: 150 mPa·s | Shelf Life: 12 months | Packaging: 20kg drum','waterproofing',1,'2026-04-01 16:02:35','2026-04-01 16:26:38',NULL,NULL),(2,'SealBoss ElastoPUR 200 Flexible PU Resin','Two-component flexible polyurethane resin for permanent elastic crack sealing. Unlike foam resins, ElastoPUR cures into a solid rubber-like material that accommodates ongoing structural movement — ideal for expansion joints and cracks in Hong Kong buildings subject to thermal cycling and settlement.','SealBoss','ElastoPUR-200','kg',520.00,'https://d2xsxph8kpxj0f.cloudfront.net/310519663429127370/EqJqhhxWWJKtKB68YEvggw/sealboss-elastopur-200_2771f440.png','Type: Two-component flexible PU gel | Mixing Ratio: 1:1 by volume | Cure Time: 5-15 minutes | Shore Hardness: A30 | Elongation: 400% | Shelf Life: 12 months | Packaging: 10kg kit (2x 5kg)','waterproofing',1,'2026-04-01 16:02:36','2026-04-01 16:26:38',NULL,NULL),(3,'Sika Injection 451 Epoxy Resin','Low-viscosity two-component epoxy injection resin for structural crack repair. Penetrates hairline cracks as fine as 0.1mm and cures to a rigid bond stronger than the surrounding concrete. Used for structural restoration of load-bearing elements — columns, beams, and shear walls — across Hong Kong construction projects.','Sika','Injection-451','kg',680.00,'https://d2xsxph8kpxj0f.cloudfront.net/310519663429127370/EqJqhhxWWJKtKB68YEvggw/sika-injection-451_875a7b12.jpg','Type: Two-component epoxy | Viscosity: 200 mPa·s (mixed) | Mixing Ratio: 2:1 by weight | Pot Life: 60 min at 23°C | Compressive Strength: 60 MPa | Tensile Strength: 30 MPa | Packaging: 6kg kit','waterproofing',1,'2026-04-01 16:02:36','2026-04-01 16:26:38',NULL,NULL),(4,'Sika Injection 304 Acrylic Gel','Water-reactive acrylic injection gel for curtain grouting and soil stabilisation behind retaining walls. The gel permeates through fine soil and fills voids to create a waterproof barrier outside the structure. Commonly used in Hong Kong basement excavation projects where external waterproofing access is limited.','Sika','Injection-304','litre',450.00,'https://d2xsxph8kpxj0f.cloudfront.net/310519663429127370/EqJqhhxWWJKtKB68YEvggw/sika-injection-304_7fc3cef6.jpg','Type: Acrylic gel (water-reactive) | Viscosity: Similar to water | Gel Time: Adjustable 10s-30min | pH: 7-8 (neutral) | Shrinkage: <5% | Packaging: 25L drum','waterproofing',1,'2026-04-01 16:02:36','2026-04-01 16:26:39',NULL,NULL),(5,'SikaLastic-152 Liquid Membrane','Two-component cementitious liquid-applied waterproof membrane for rooftops, balconies, and wet areas. Brush or roller-applied in two coats to form a seamless, crack-bridging membrane. One of the most widely specified liquid membranes in Hong Kong for bathroom renovations and flat roof waterproofing.','Sika','SikaLastic-152','kg',280.00,'https://d2xsxph8kpxj0f.cloudfront.net/310519663429127370/EqJqhhxWWJKtKB68YEvggw/sikalastic-152_8791daf8.jpg','Type: Two-component cementitious | Application: Brush, roller, or spray | Thickness: 2mm (2 coats) | Coverage: 1.5 kg/m² per mm | Crack Bridging: >2mm | Elongation: >50% | Packaging: 25kg kit','waterproofing',1,'2026-04-01 16:02:36','2026-04-01 16:26:39',NULL,NULL),(6,'Fosroc Nitoprime 25 Primer','Solvent-free epoxy primer for preparing concrete surfaces before liquid membrane application. Seals the substrate pores and provides a strong bond coat for subsequent waterproofing layers. Essential first step for any professional membrane installation — skipping primer is the most common cause of membrane delamination.','Fosroc','Nitoprime-25','kg',350.00,'https://d2xsxph8kpxj0f.cloudfront.net/310519663429127370/EqJqhhxWWJKtKB68YEvggw/fosroc-nitoprime-25_078d17cb.png','Type: Two-component solvent-free epoxy | Coverage: 0.2-0.3 kg/m² | Pot Life: 30 min at 30°C | Overcoat Time: 4-24 hours | VOC: Zero | Packaging: 5kg kit','waterproofing',1,'2026-04-01 16:02:37','2026-04-01 16:26:39',NULL,NULL),(7,'Sika Primer MB Moisture Barrier','Epoxy-based moisture barrier and primer for use on damp or green concrete before membrane application. Tolerates up to 95% relative humidity in the substrate — critical for Hong Kong\'s tropical climate where concrete rarely dries fully before waterproofing deadlines hit.','Sika','Primer-MB','kg',420.00,'https://d2xsxph8kpxj0f.cloudfront.net/310519663429127370/EqJqhhxWWJKtKB68YEvggw/sika-primer-mb_a8e4905f.jpg','Type: Two-component epoxy | Moisture Tolerance: Up to 95% RH | Coverage: 0.3-0.5 kg/m² | Cure Time: 12-24 hours | VOC: <50 g/L | Packaging: 10kg kit','waterproofing',1,'2026-04-01 16:02:37','2026-04-01 16:26:39',NULL,NULL),(8,'Sika Caulking Sealant 11 FC','One-component polyurethane sealant for sealing joints, gaps, and penetrations in waterproofing systems. Paintable, flexible, and UV-resistant — used to seal around pipe penetrations, window frames, and expansion joints before membrane application. A versatile workhorse sealant found on virtually every waterproofing job site in Hong Kong.','Sika','Sikaflex-11FC','tube',85.00,'https://d2xsxph8kpxj0f.cloudfront.net/310519663429127370/EqJqhhxWWJKtKB68YEvggw/sikaflex-11fc_e55f1dcb.jpg','Type: One-component PU sealant | Volume: 310ml cartridge | Movement: ±25% | Shore A: 40 | Skin Time: 60 min | Full Cure: 3-5 days | Paintable: Yes | UV Resistant: Yes','waterproofing',1,'2026-04-01 16:02:37','2026-04-01 16:26:39',NULL,NULL),(9,'Grease Coupler Set for Injection Packers','Heavy-duty grease coupler set designed to connect injection pumps to standard Zerk-fitting packers. Includes quick-release coupler, high-pressure hose adapter, and spare O-rings. Without a proper coupler, you cannot connect your pump to the packers — this is the essential link between pump and packer on every injection job.','SealBoss','GC-100','set',180.00,'https://d2xsxph8kpxj0f.cloudfront.net/310519663429127370/EqJqhhxWWJKtKB68YEvggw/sealboss-grease-coupler_8ab924f4.png','Contents: 2x Quick-release couplers | 2x Hose adapters (1/4\" NPT) | 10x Spare O-rings | Pressure Rating: 250 bar | Fitting: Standard Zerk | Material: Hardened steel with brass seats','waterproofing',1,'2026-04-01 16:02:37','2026-04-01 16:26:40',NULL,NULL),(10,'Reinforcing Fabric Mesh for Membranes','Alkali-resistant polyester reinforcing mesh embedded between membrane coats at corners, joints, and penetrations. Prevents membrane cracking at stress points and provides additional tensile strength. Standard practice on all professional membrane jobs — building inspectors in Hong Kong will flag any membrane installation without reinforcing at detail areas.','Sika','SikaLastic Fleece','roll',220.00,'https://d2xsxph8kpxj0f.cloudfront.net/310519663429127370/EqJqhhxWWJKtKB68YEvggw/sikalastic-fleece-mesh_c250d2c0.jpg','Material: Alkali-resistant polyester | Width: 200mm | Length: 50m per roll | Weight: 120 g/m² | Elongation: >40% | Application: Embed between membrane coats at corners, joints, pipes','waterproofing',1,'2026-04-01 16:02:37','2026-04-01 16:26:40',NULL,NULL);
