INSERT INTO `equipment_bundles` VALUES (1,'Waterproofing Starter Kit','waterproofing-starter-kit','Everything you need to get started with PU injection waterproofing. Includes a PU pump, injection packers, and a caulking gun for sealant application. Perfect for small to medium crack injection jobs on walls and slabs.',NULL,350.00,1400.00,4200.00,20,'waterproofing',1,1,1,'2026-04-02 03:58:53','2026-04-02 03:58:53',NULL,NULL),(2,'Heavy Duty Waterproofing Package','heavy-duty-waterproofing-package','Professional waterproofing setup for large-scale injection and membrane work. Includes a large PU pump, brass packers, power sprayer for membrane application, and a mixing plant for grout preparation. Ideal for basement tanking, tunnel repairs, and commercial waterproofing projects.',NULL,800.00,3200.00,9600.00,25,'waterproofing',1,1,2,'2026-04-02 03:58:54','2026-04-02 03:58:54',NULL,NULL),(3,'Floor Preparation Package','floor-preparation-package','Complete floor surface preparation kit for grinding, scarifying, and polishing concrete floors. Includes a floor grinder, scarifier, and polisher — everything needed to prep a floor from rough concrete to a smooth finish. Suitable for warehouse floors, car parks, and commercial spaces.',NULL,650.00,2600.00,7800.00,20,'surface_prep',1,1,3,'2026-04-02 03:58:55','2026-04-02 03:58:55',NULL,NULL),(4,'Concrete Pour Essentials','concrete-pour-essentials','All the key tools for a concrete pour — vibrator for consolidation, mixer for small batches, and a plate compactor for sub-base preparation. Covers the full workflow from ground prep through to concrete placement. Ideal for slabs, footings, and small structural pours.',NULL,550.00,2200.00,6600.00,15,'concrete',1,1,4,'2026-04-02 03:58:56','2026-04-02 03:58:56',NULL,NULL),(5,'Steel Surface Prep Kit','steel-surface-prep-kit','Complete steel surface preparation toolkit for rust removal, paint stripping, and weld cleaning. Includes a needle scaler, chisel scaler, and rotary descaler — covering everything from precision cleaning to large-area mill scale removal. Essential for marine maintenance, structural steel, and recoating projects.',NULL,500.00,2000.00,6000.00,20,'surface_prep',1,1,5,'2026-04-02 03:58:57','2026-04-02 03:58:57',NULL,NULL),(6,'Rebar Works Package','rebar-works-package','Everything for on-site rebar fabrication — cutter, bender, and tying gun. Cut, bend, and tie reinforcing bar without needing a fabrication yard. Speeds up slab reinforcement by 5x compared to manual methods. Perfect for remote sites or projects where pre-fab delivery is impractical.',NULL,550.00,2200.00,6600.00,20,'concrete',1,1,6,'2026-04-02 03:58:58','2026-04-02 03:58:58',NULL,NULL),(30001,'Complete Rigging Kit','complete-rigging-kit','Everything you need for a safe, compliant lift in one kit. Includes a 1-tonne chain block, bow and dee shackles, round slings, a flat webbing sling, and corner protectors — all from certified manufacturers. Ideal for marine, construction, and plant maintenance operations. Saves you sourcing individual items and ensures all components are rated and compatible.',NULL,429.00,1743.00,5126.00,15,'Rigging',1,1,10,'2026-04-03 01:34:58','2026-04-03 01:34:58',NULL,NULL);
