INSERT INTO `equipment_categories` VALUES (1,'Power Tools','power-tools','Professional-grade power tools for hire in Hong Kong. From hammer drills and angle grinders to circular saws and jigsaws — EquipHK stocks leading brands including Makita, Hilti, DeWalt, and Milwaukee. Whether you\'re a DIY homeowner or a Tier 1 contractor, our power tool fleet is PAT-tested, serviced, and ready for same-day delivery across Hong Kong Island, Kowloon, and the New Territories.',NULL,'both',0,1,'2026-03-28 13:50:03','2026-04-02 04:03:01'),(2,'Scaffolding & Access','scaffolding-access','Scaffolding systems, towers, and access platforms for rent across Hong Kong. Our range includes Dr Scaffold modular systems, aluminium towers, safety railings, outriggers, and ladder spans — all compliant with Hong Kong\'s Construction Sites (Safety) Ordinance Cap. 59. Ideal for façade works, painting, M&E installation, and building maintenance. Delivered, erected, and collected by our trained crew.',NULL,'both',1,1,'2026-03-28 13:50:04','2026-04-02 04:03:01'),(3,'Safety Equipment','safety-equipment','Safety equipment and PPE hire for construction sites in Hong Kong. From fall arrest harnesses and safety nets to fire extinguishers and gas detectors — we supply the gear that keeps your team compliant and protected. All equipment meets Hong Kong Labour Department standards and is regularly inspected. Available for short-term hire or long-term project supply.',NULL,'both',2,1,'2026-03-28 13:50:04','2026-04-02 04:03:02'),(4,'Measuring & Leveling','measuring-leveling','Precision measuring and leveling instruments for rent in Hong Kong. Laser levels, total stations, rotary lasers, optical levels, and distance meters from Hilti, Leica, and Bosch. Calibrated and ready for setting out, floor leveling, façade alignment, and survey work. Suitable for interior fit-out through to large-scale civil engineering projects.',NULL,'both',3,1,'2026-03-28 13:50:04','2026-04-02 04:03:02'),(5,'Welding & Cutting','welding-cutting','Welding and cutting equipment for hire across Hong Kong. MIG, TIG, and stick welders plus plasma cutters, oxy-fuel sets, and grinding tools. Our fleet covers everything from structural steel fabrication to on-site repair and maintenance. All machines are tested, serviced, and supplied with leads and accessories. Available for daily, weekly, or monthly rental.',NULL,'both',4,1,'2026-03-28 13:50:04','2026-04-02 04:03:02'),(6,'Pneumatic Tools','pneumatic-tools','Pneumatic tools and air-powered equipment for rent in Hong Kong. Breakers, chipping hammers, impact wrenches, nail guns, and air compressors — built for heavy-duty demolition, steel fixing, and finishing work. Pneumatic tools deliver higher power-to-weight ratios than electric equivalents, making them the go-to choice for demanding site conditions.',NULL,'both',5,1,'2026-03-28 13:50:05','2026-04-02 04:03:02'),(7,'Hydraulic Equipment','hydraulic-equipment','Hydraulic equipment for hire in Hong Kong. Hydraulic jacks, power packs, rams, cutters, and spreaders for heavy lifting, structural jacking, and rescue operations. Our hydraulic fleet handles loads from 5 to 100+ tonnes and is maintained to manufacturer specifications. Ideal for bridge works, building underpinning, and marine construction.',NULL,'both',6,1,'2026-03-28 13:50:05','2026-04-02 04:03:03'),(8,'Pumps & Fluid Handling','pumps-fluid-handling','Pumps and fluid handling equipment for rent across Hong Kong. Submersible pumps, dewatering systems, pressure washers, PU injection pumps, and diesel transfer kits. Whether you need to dewater an excavation, clean a construction site, or inject waterproofing resin — we have the right pump for the job. Available with hoses, fittings, and operator guidance.',NULL,'both',7,1,'2026-03-28 13:50:05','2026-04-02 04:03:03'),(9,'Chainsaws & Outdoor','chainsaws-outdoor','Chainsaws and outdoor power equipment for hire in Hong Kong. Petrol and battery-powered chainsaws, hedge trimmers, brush cutters, and blowers from Husqvarna, Stihl, and Makita. Suitable for tree surgery, land clearing, landscaping, and typhoon damage cleanup. All machines are sharp, fueled, and ready to cut.',NULL,'both',8,1,'2026-03-28 13:50:05','2026-04-02 04:03:03'),(10,'Batteries & Power','batteries-power','Batteries, chargers, and portable power solutions for rent in Hong Kong. Spare battery packs for Makita, Milwaukee, Hilti, and DeWalt cordless systems, plus portable generators and inverters for off-grid power. Keep your cordless tools running all day without downtime. We stock the most common battery platforms so you can swap and go.',NULL,'both',9,1,'2026-03-28 13:50:06','2026-04-02 04:03:03'),(11,'Hand Tools & Accessories','hand-tools-accessories','Hand tools and accessories for hire in Hong Kong. Pipe wrenches, bolt cutters, torque wrenches, cable pullers, and specialist hand tools for plumbing, electrical, and mechanical trades. When you need a specific tool for a one-off job, renting makes more sense than buying. Our hand tool range covers the trades from A to Z.',NULL,'both',10,1,'2026-03-28 13:50:06','2026-04-02 04:03:04'),(12,'Compressors & Air','compressors-air','Air compressors and compressed air equipment for rent across Hong Kong. Portable and towable compressors from 2 CFM to 400+ CFM, plus air dryers, receivers, and hose reels. Power your pneumatic tools, spray painting, sandblasting, and tyre inflation on any site. Diesel and electric options available for indoor and outdoor use.',NULL,'both',11,1,'2026-03-28 13:50:06','2026-04-02 04:03:04'),(13,'Specialized Equipment','specialized-equipment','Specialized construction equipment for hire in Hong Kong. Plate compactors, concrete mixers, vibrators, generators, lighting towers, and other plant that doesn\'t fit neatly into one category. If you need something unusual for a specific job, chances are we have it — or we can source it. Contact us for bespoke equipment solutions.',NULL,'both',12,1,'2026-03-28 13:50:06','2026-04-02 04:03:04'),(30002,'Waterproofing','waterproofing','Waterproofing equipment and supplies for rent and purchase in Hong Kong. PU injection pumps, injection packers, grout plants, membrane sprayers, sealant guns, and mixing equipment for crack injection, basement tanking, tunnel repair, and roof waterproofing. We also stock consumables including PU resin, epoxy grout, primer, and reinforcing mesh. Everything you need to stop water — from a single crack to a full basement.','Droplets','both',0,1,'2026-04-01 15:42:37','2026-04-02 04:03:04'),(60001,'Surface Preparation','surface-preparation','Surface preparation tools and equipment for hire in Hong Kong. Floor grinders, sandblasters, needle scalers, scarifiers, polishers, and planers for concrete, steel, and coating removal. Whether you\'re preparing a warehouse floor for epoxy coating, removing rust from structural steel, or stripping old paint from a ship\'s hull — our surface prep fleet gets the substrate ready for whatever comes next.','Construction','both',99,1,'2026-04-02 03:20:28','2026-04-02 04:03:04'),(60002,'Concrete & Formwork','concrete-formwork','Concrete and formwork equipment for rent across Hong Kong. Vibrators, mixers, rebar tools, formwork systems, power trowels, and curing equipment for pours of all sizes. From a small residential footing to a multi-storey commercial slab — we supply the tools that make concrete work faster, stronger, and more consistent. All equipment is cleaned, tested, and delivered to site.','HardHat','both',99,1,'2026-04-02 03:52:03','2026-04-02 04:03:05'),(90001,'Rigging','rigging','Professional rigging equipment for lifting, hoisting, and load securing operations.','🪝','both',109,1,'2026-04-03 01:19:51','2026-04-03 01:19:51'),(120001,'Test Category','test-category-rbac',NULL,NULL,'both',0,1,'2026-04-05 13:28:12','2026-04-05 13:28:12');
/*!40000 ALTER TABLE `equipment_categories` ENABLE KEYS */;
