INSERT INTO `equipment_items` VALUES (1,4,'360* Lazer level','Tired of squinting at spirit levels in a cramped flat? This Hilti 360° laser level projects a perfectly flat, bright line across your entire room, instantly simplifying everything from hanging art precisely to installing kitchen cabinets like a pro. Get your DIY projects done right, the first time, without the hassle.','Hilti','PM 4-M',470.00,2340.00,9340.00,'fixed','https://d2xsxph8kpxj0f.cloudfront.net/310519663429127370/EqJqhhxWWJKtKB68YEvggw/equipment-photos/1774792976236-d7ilhpte03v.jpg',NULL,'good','maintenance',1,0,NULL,1,0,'2026-03-28 13:22:10','2026-04-02 03:46:42',28,NULL,'approved',0,NULL,NULL,NULL,'none',NULL,NULL),(2,2,'Safety Railing 2 Rung Span','The Dr Scaffold SRP-3 Safety Railing 2 Rung Span provides essential fall protection and demarcation for elevated work platforms and scaffolding systems in Hong Kong\'s dynamic construction environment. Engineered for rapid deployment and robust performance, this railing ensures worker safety and compliance with local site regulations. Its durable construction and easy integration make it an indispensable asset for any rental fleet or construction project.','Dr Scaffold','SRP-3',60.00,250.00,750.00,'fixed','https://via.placeholder.com/400x300?text=Dr%20Scaffold%20Safety%20R','Material: High-strength galvanized steel | Rungs: 2 | Length: Approximately 2.4m (8 feet) | Height: Approximately 1.0m (3.3 feet) | Weight: Approximately 10-15 kg | Compatibility: Designed for Dr Scaffold modular systems | Finish: Corrosion-resistant coating','good','maintenance',3,1,NULL,1,0,'2026-03-28 13:22:10','2026-04-17 02:47:17',5,'https://d2xsxph8kpxj0f.cloudfront.net/310519663429127370/EqJqhhxWWJKtKB68YEvggw/equipment-photos/1776394036954-cie469ver2k.jpg','pending',0,'[\"https://d35rpq4gusjz9h.cloudfront.net/files/121183/products/810401/121183_2_202112091225086201286_raw.jpg\",\"https://news.gsmedtech.com/wp-content/uploads/2024/05/news-v1-52.png\",\"https://www.turboscaffolding.com.au/catalog/product/original/3.0m-wide-new.jpg\"]','http://www.takkeeltd.com.hk/productdetails_image/dr/drscaffold/dr_fiberglass_scaffold_p1_m.jpg',NULL,'none',NULL,NULL),(3,60001,'Cadillac Sand Blaster','Tired of battling stubborn rust on your old iron gate or prepping that concrete wall for a fresh coat of paint? Our Cadillac Sand Blaster makes quick work of tough surface jobs, stripping away years of grime with surprising ease. Get professional-grade results on your next renovation, saving time and effort compared to elbow grease alone – perfect for rejuvenating everything from metal railings to exposed brickwork around your Sai Kung villa.',NULL,'QB7-V002',560.00,2820.00,11260.00,'fixed','https://via.placeholder.com/400x300?text=Cadillac%20Sand%20Blaste','Capacity: 7 Liters (2 Gallons) | Operating Pressure: 60-125 PSI | Air Consumption: 6-25 CFM | Nozzle Size: 2.4mm, 2.7mm, 3.2mm | Hose Length: 2.5 meters (8 feet) | Weight (empty): 12 kg | Dimensions: 60cm H x 30cm W x 30cm D | Media Type: Silica Sand, Glass Beads, Aluminum Oxide','good','maintenance',1,0,NULL,1,0,'2026-03-28 13:22:10','2026-05-18 12:49:10',60002,NULL,'rejected',0,'[\"https://image.yodobashi.com/product/100/000/001/008/949/627/100000001008949627_10203.jpg\",\"https://www.demeq.com/img/products/qb/carousel/QB7-maletin-E.webp\"]',NULL,NULL,'none',NULL,NULL),(4,3,'Fall Arrester','Alright, let\'s get that rooftop waterproofing project or external AC unit installation done safely! Our Haru Fall Arrester is your trusty, no-nonsense companion for working at heights, keeping you secure whether you\'re fixing tiles or repainting a tricky exterior. Rent it for peace of mind – because a safe job is a good job, every time.','HARU','HE-6N',210.00,1050.00,4200.00,'fixed','https://d2xsxph8kpxj0f.cloudfront.net/310519663429127370/EqJqhhxWWJKtKB68YEvggw/equipment-photos/1774792996702-8q75j1v3mv9.jpg','Material: High-strength steel/aluminum alloy casing | Cable Material: Galvanized steel wire rope | Cable Length: 6 meters | Maximum Working Load: 150 kg | Activation Speed: 0.8 m/s | Braking Distance: Less than 0.5 meters | Connector: Swivel snap hook with fall indicator | Standards: EN360:2002 compliant | Weight: Approximately 4.5 kg | Dimensions: 250mm x 200mm x 90mm (approximate)','good','maintenance',2,1,NULL,1,0,'2026-03-28 13:22:11','2026-04-02 03:46:42',12,NULL,'approved',0,NULL,NULL,NULL,'none',NULL,NULL),(5,3,'Fall Arrester','Working at height in , whether it\'s a quick balcony repair or a full exterior paint job, demands absolute safety. Our Viraj Standard Fall Arrester is your invisible guardian, instantly locking if you slip, giving you peace of mind to focus on the task, not the \'what ifs\'. It\'s tough, reliable, and keeps you secure so you can tackle those tricky elevated projects with confidence.','Viraj','SF-RFA-6W',210.00,1050.00,4200.00,'fixed','https://via.placeholder.com/400x300?text=Viraj%20Fall%20Arrester','Length: 6 meters (20 ft) | Lifeline Material: Galvanized Steel Wire Rope (4.5 mm diameter) | Casing Material: High-strength Polymer | Arresting Force: Max 6 kN | Weight Capacity: 100 kg | Standards: EN 360:2002 | Connectors: Swivel snap hook with fall indicator on lifeline, Carabiner on casing','good','maintenance',4,1,NULL,1,0,'2026-03-28 13:22:11','2026-05-12 23:13:05',12,'https://d2xsxph8kpxj0f.cloudfront.net/310519663429127370/EqJqhhxWWJKtKB68YEvggw/equipment-photos/1778627585591-ca1lw1duekc.jpg','pending',0,NULL,'https://i1apiwww.wahtaihongsafety.com.hk/erp/imgupload/wahtaihong/product_gallery/2104/tbn934_%E6%9C%AA%E5%91%BD%E5%90%8D.jpg',NULL,'none',NULL,NULL),(6,13,'AC Delco Marine Battery','Need reliable juice for your boat or off-grid project around Sai Kung? Our AC Delco Marine Battery (Standard) delivers consistent, long-lasting power, ensuring your essential equipment keeps running without a hitch. Skip the upfront cost and simply rent this dependable power source for those weekend repairs or temporary setups.','ACDelco','M24-75',190.00,940.00,3760.00,'fixed','https://d2xsxph8kpxj0f.cloudfront.net/310519663429127370/EqJqhhxWWJKtKB68YEvggw/equipment-photos/1774793009940-b7q14tfecpq.png','Voltage: 12V | Capacity (Reserve Capacity): 160 minutes | Cold Cranking Amps (CCA): 600A | Marine Cranking Amps (MCA): 750A | Weight: Approximately 42 lbs (19.05 kg) | Dimensions (L x W x H): Approximately 10.75\" x 6.8\" x 9.4\" (273mm x 173mm x 239mm) | Terminal Type: Dual SAE & Stud','good','available',1,1,NULL,1,0,'2026-03-28 13:22:11','2026-04-01 15:12:25',66,NULL,'approved',0,NULL,NULL,NULL,'none',NULL,NULL),(7,13,'Equipment Battery','The Cheetah NS40ZL Equipment Battery is a robust and reliable power solution engineered for demanding construction and rental applications in Hong Kong. Designed to provide consistent and long-lasting performance, this maintenance-free battery ensures critical equipment operates efficiently on busy job sites. Its durable construction and high cold cranking amps make it an ideal choice for a wide range of machinery requiring dependable starting power and auxiliary energy.','Cheetah','NS40ZL',60.00,250.00,700.00,'fixed','https://d2xsxph8kpxj0f.cloudfront.net/310519663429127370/EqJqhhxWWJKtKB68YEvggw/equipment-photos/1774781096082-suuc6qbi97k.webp','Voltage: 12V | Capacity (20HR): 35 Ah | Cold Cranking Amps (CCA): 270A | Terminal Type: Small Post | Dimensions (LxWxH): 197mm x 129mm x 227mm | Weight: Approximately 9.5 kg | Battery Type: Lead-Acid, Maintenance-Free','good','available',1,1,NULL,1,0,'2026-03-28 13:22:11','2026-04-02 03:46:43',66,NULL,'approved',0,NULL,NULL,NULL,'none',NULL,NULL),(8,4,'Laser Level','Tired of crooked picture frames or wonky shelf installations in your flat? Grab our Bosch Standard Laser Level and achieve perfectly straight lines with zero fuss. This little German marvel projects crisp, accurate guides, making everything from tiling your bathroom to hanging art a breeze – no more eyeballing!','Bosch','GLL 30 G Professional',210.00,1050.00,4200.00,'fixed','https://d2xsxph8kpxj0f.cloudfront.net/310519663429127370/EqJqhhxWWJKtKB68YEvggw/equipment-photos/1774779720135-me2hgu8kcao.jpg','Accuracy: ±0.8 mm/m | Working Range: up to 10 m | Laser Diode: 500 – 540 nm, < 5 mW | Laser Class: 2 | Self-leveling Range: ±4° | Power Supply: 2 x 1.5 V LR6 (AA) | Tripod Thread: 1/4 inch | Weight: 0.25 kg | Dimensions (L x W x H): 72 x 55 x 71 mm | Operating Temperature: -5 to 40 °C | Storage Temperature: -20 to 70 °C','good','available',1,1,NULL,1,0,'2026-03-28 13:22:12','2026-03-29 15:08:30',28,NULL,'approved',1,NULL,NULL,NULL,'none',NULL,NULL),(9,4,'Digital Angle Gauge','The Klein Tools 935DAGL Digital Angle Gauge is an essential precision instrument for construction and renovation projects, enabling rapid and accurate measurement of angles for framing, pipe bending, and equipment setup. Its magnetic base and clear backlit display ensure reliable readings in diverse job site conditions, making it an indispensable tool for professionals requiring consistent angular accuracy. This compact and durable gauge enhances efficiency for tasks ranging from carpentry and plumbing to HVAC installations, ensuring precise alignment and fit.','Klein Tools','935DAGL',120.00,590.00,2340.00,'fixed','https://d2xsxph8kpxj0f.cloudfront.net/310519663429127370/EqJqhhxWWJKtKB68YEvggw/equipment-photos/1774779714550-s14q2xnvwef.jpg','Accuracy: +/- 0.1 degrees at 0 and 90 degrees, +/- 0.2 degrees at other angles | Range: 0 to 90 degrees (4 x 90 degrees for full 360-degree measurement) | Display: Backlit LCD | Power: 2 x AAA batteries | Auto-off: Yes (after 3 minutes of inactivity) | Mounting: Magnetic base | Dimensions: Approximately 60mm x 60mm x 32mm | Weight: Approximately 100g (without batteries)','good','available',1,1,NULL,1,0,'2026-03-28 13:22:12','2026-04-02 03:48:55',30,NULL,'approved',1,NULL,NULL,NULL,'none',NULL,NULL),(10,13,'Elephant 1 Ton Chain Block','Need to hoist something heavy in your workshop or renovation project without breaking your back (or the bank)? Our trusty Elephant 1T Chain Block is your go-to for safely lifting engines, beam sections, or even that oversized antique cabinet. It\'s built tough for reliable, smooth operation, making those tricky lifts a breeze for any serious DIYer or small-scale contractor.','Elephant Chain Block Co.','C-21',230.00,1130.00,4500.00,'fixed','https://d2xsxph8kpxj0f.cloudfront.net/310519663429127370/EqJqhhxWWJKtKB68YEvggw/equipment-photos/1774793019263-clhe2hih8kv.png','Capacity: 1 Ton (1000 kg) | Standard Lift: 2.5 m | Test Load: 1500 kg | Chain Diameter: 6.3 mm | Headroom (Min. Distance between Hooks): 280 mm | Net Weight (for 2.5m lift): 12 kg | Hand Chain Pull to Lift Rated Load: 310 N','good','maintenance',1,3,NULL,1,0,'2026-03-28 13:22:12','2026-04-01 15:33:20',65,NULL,'approved',0,NULL,NULL,NULL,'none',NULL,NULL),(11,4,'Walking Measuring Wheel','Tired of wrestling with a tape measure on uneven terrain or sprawling construction sites? Grab our Togoshi Standard Walking Measuring Wheel and effortlessly clock distances for fencing, landscaping, or even planning that new flat renovation. This Japanese-engineered workhorse makes solo surveying a breeze, ensuring accurate material estimates without the fuss.','Togoshi','TWM-130',110.00,560.00,2240.00,'fixed','https://d2xsxph8kpxj0f.cloudfront.net/310519663429127370/EqJqhhxWWJKtKB68YEvggw/equipment-photos/1774793028560-5x4qdgbfxbx.png','Wheel Diameter: 318mm (12.5 inches) | Measuring Range: Up to 9999.9 meters | Accuracy: Typically +/- 0.5% | Handle Type: Telescopic, foldable | Counter: Mechanical, reset button | Tire Material: Durable rubber | Weight: Approximately 2.0 kg | Construction: Heavy-duty plastic and aluminum alloy','good','available',1,1,NULL,1,0,'2026-03-28 13:22:12','2026-04-02 03:46:43',30,NULL,'approved',0,NULL,NULL,NULL,'none',NULL,NULL),(14,13,'1Ton  Chain Block','Tired of wrestling with heavy loads on your solo projects or tight worksites? This Taiyu 1T chain block is your sturdy, no-fuss lifting partner, making light work of everything from engine swaps in your garage to positioning steel beams in cramped alleys. It’s surprisingly compact yet packs serious muscle, helping you safely conquer those tricky lifts without breaking your back (or the bank).','Taiyu','HSZ-VT',230.00,1130.00,4500.00,'fixed','https://d2xsxph8kpxj0f.cloudfront.net/310519663429127370/EqJqhhxWWJKtKB68YEvggw/equipment-photos/1775178746822-mym5kdmk70b.jpg','Capacity: 1000 kg (1 Ton) | Standard Lift: 3 m (can be customized) | Test Load: 1500 kg | Headroom: 300 mm | Chain Diameter: 6 mm | Number of Load Chain Falls: 1 | Net Weight (for 3m lift): Approximately 12.5 kg | Hand Pull to Rated Load: 320 N','good','maintenance',1,1,NULL,1,0,'2026-03-28 13:22:13','2026-04-03 01:17:58',65,NULL,'approved',0,'[\"https://www.taiyu-chem.co.jp/assets/img/top/pict_product_2.jpg\",\"https://taiyu-corp.com/img/products/products_pic02.jpg\",\"https://taiyu-corp.com/img/products/products_pic04.jpg\"]',NULL,NULL,'none',NULL,NULL),(15,13,'Magnum Hydraulic Drill','The Xcalibre Magnum Hydraulic Drill (Mag 15) is a robust and efficient drilling solution, ideal for demanding construction and utility projects across Hong Kong. Its powerful hydraulic motor ensures consistent performance for drilling through concrete, asphalt, and rock, making it a valuable asset for trenching, utility installation, and demolition tasks. This versatile tool offers superior power-to-weight ratio and is designed for reliable operation in challenging urban and infrastructure environments.','Xcalibre','Mag 15',650.00,3000.00,9500.00,'fixed','https://via.placeholder.com/400x300?text=Xcalibre%20Magnum%20Hydr','Power: 12.5 hp (9.3 kW) hydraulic motor | Weight: 30 kg (power pack) / 10 kg (drill head) | Drilling Capacity: Up to 150 mm diameter | Flow Rate: 20-30 lpm | Pressure: 140 bar (2000 psi) | Dimensions (Power Pack): 600 x 400 x 500 mm','good','maintenance',2,1,NULL,1,0,'2026-03-28 13:22:13','2026-05-18 12:47:43',64,NULL,'re